describe('File Upload - Unsupported File Type Error', () => {
  beforeEach(() => {
    cy.visit('/upload');
    cy.get('input[type="file"]').as('fileInput');
  });

  it('should display error message when uploading unsupported file type', () => {
    const fileName = 'document.exe';
    cy.fixture('unsupported/document.exe', 'binary').then(fileContent => {
      cy.get('@fileInput').selectFile({
        contents: Cypress.Buffer.from(fileContent),
        fileName: fileName,
        mimeType: 'application/x-msdownload'
      });
    });

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Unsupported file type');
    cy.get('[data-testid="upload-button"]').should('be.disabled');
  });

  it('should display specific error for multiple unsupported file types', () => {
    const unsupportedFiles = [
      { name: 'script.bat', mime: 'application/x-bat' },
      { name: 'archive.zip', mime: 'application/zip' },
      { name: 'image.bmp', mime: 'image/bmp' }
    ];

    unsupportedFiles.forEach(file => {
      cy.get('@fileInput').selectFile({
        contents: Cypress.Buffer.from('fake content'),
        fileName: file.name,
        mimeType: file.mime
      });

      cy.get('[data-testid="error-message"]').should('be.visible');
      cy.get('[data-testid="error-message"]').should('contain', 'not supported');
      cy.get('[data-testid="file-preview"]').should('not.exist');
    });
  });

  it('should allow supported file types without error', () => {
    const supportedFile = 'document.pdf';
    cy.fixture('supported/document.pdf', 'binary').then(fileContent => {
      cy.get('@fileInput').selectFile({
        contents: Cypress.Buffer.from(fileContent),
        fileName: supportedFile,
        mimeType: 'application/pdf'
      });
    });

    cy.get('[data-testid="error-message"]').should('not.exist');
    cy.get('[data-testid="file-preview"]').should('be.visible');
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');
  });

  it('should clear error message when user selects a valid file after invalid attempt', () => {
    cy.get('@fileInput').selectFile({
      contents: Cypress.Buffer.from('fake content'),
      fileName: 'invalid.exe',
      mimeType: 'application/x-msdownload'
    });

    cy.get('[data-testid="error-message"]').should('be.visible');

    cy.fixture('supported/document.pdf', 'binary').then(fileContent => {
      cy.get('@fileInput').selectFile({
        contents: Cypress.Buffer.from(fileContent),
        fileName: 'document.pdf',
        mimeType: 'application/pdf'
      });
    });

    cy.get('[data-testid="error-message"]').should('not.exist');
    cy.get('[data-testid="file-preview"]').should('be.visible');
  });
});
